import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testThreeScores() {
        Assert.assertEquals(listOf(10, 30, 60), runningTotal(listOf(10, 20, 30)))
    }

    @Test
    fun testSingleScore() {
        Assert.assertEquals(listOf(5), runningTotal(listOf(5)))
    }

    @Test
    fun testEmpty() {
        Assert.assertEquals(emptyList<Int>(), runningTotal(emptyList()))
    }
}
